css:
.ww{display:grid;gap:clamp(1.5rem,4vw,3.5rem);align-items:center}
@media (min-width:992px){.ww{grid-template-columns:minmax(0,33rem) minmax(0,1fr)}}
.wh{position:relative;width:100%;max-width:34rem;margin-inline:auto;container-type:inline-size}
.wh svg{width:100%;height:auto;display:block;overflow:visible;-webkit-tap-highlight-color:transparent;user-select:none}
.sg{pointer-events:none}
.bd{fill:color-mix(in oklab,var(--d) 20%,#f3f1e2);stroke:#e9e6d2;stroke-width:3;transition:fill .25s}
.bn{fill:var(--d);stroke:#e9e6d2;stroke-width:3}
.sh{transition:transform .25s cubic-bezier(.3,.7,.3,1);transform-origin:250px 250px}
.ic{stroke:#15261a;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.lb{position:absolute;transform:translate(-50%,-50%);color:#15261a;font:700 2.7cqw/1 var(--os-font-body);white-space:nowrap;pointer-events:none}
.ht{fill:transparent;cursor:pointer;outline:none;pointer-events:all}
.hub{fill:#f3f1e2;stroke:rgba(21,38,26,.22);stroke-width:1.5}
.hub-t{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);text-align:center;pointer-events:none}.hb1{display:block;color:#15261a;font:400 5cqw/1.12 var(--os-font-heading)}.hb2{display:block;margin-top:1.2cqw;color:#3f4f3b;font:400 2.5cqw/1.2 var(--os-font-body)}
.wp{background:#f3f1e2;border-radius:14px;padding:clamp(1.4rem,3vw,2.4rem);border-top:6px solid var(--d);min-height:24rem;display:grid;transition:border-color .25s}
.pc{grid-area:1/1;visibility:hidden}
.pc h3{margin:0 0 .3em}
.sum{margin:0 0 1.6rem;color:#3f4f3b}
.st{list-style:none;margin:0;padding:0;display:grid;gap:.2rem}
.st li{display:grid;grid-template-columns:2.4rem 1fr;gap:.9rem;align-items:start;padding:.85rem 0;border-bottom:1px solid rgba(21,38,26,.22)}
.st li:last-child{border-bottom:0}
.n{display:grid;place-items:center;width:2.1rem;height:2.1rem;border-radius:999px;background:var(--df);color:var(--od);font:700 1rem var(--os-font-body)}
.t{font-weight:700;display:block;font-size:.98rem}
.dd{display:block}
@media (max-width:543px){.lb{display:none}.ic{transform:translateY(9px) scale(1.2);transform-box:fill-box;transform-origin:center}}
.s0,.lb0{--d:#db4bab;--df:#c43a97;--od:#fff}.lb0{left:50.00%;top:19.90%}
.ww[data-on="0"] .wp{--d:#db4bab;--df:#c43a97;--od:#fff}.s1,.lb1{--d:#e7691b;--df:#e7691b;--od:#15261a}.lb1{left:73.12%;top:29.48%}
.ww[data-on="1"] .wp{--d:#e7691b;--df:#e7691b;--od:#15261a}.s2,.lb2{--d:#f9bd27;--df:#f9bd27;--od:#15261a}.lb2{left:82.70%;top:52.60%}
.ww[data-on="2"] .wp{--d:#f9bd27;--df:#f9bd27;--od:#15261a}.s3,.lb3{--d:#3f8733;--df:#397b2e;--od:#fff}.lb3{left:73.12%;top:75.72%}
.ww[data-on="3"] .wp{--d:#3f8733;--df:#397b2e;--od:#fff}.s4,.lb4{--d:#03a5c3;--df:#03a5c3;--od:#0b1a1f}.lb4{left:50.00%;top:85.30%}
.ww[data-on="4"] .wp{--d:#03a5c3;--df:#03a5c3;--od:#0b1a1f}.s5,.lb5{--d:#4b87b1;--df:#3b749c;--od:#fff}.lb5{left:26.88%;top:75.72%}
.ww[data-on="5"] .wp{--d:#4b87b1;--df:#3b749c;--od:#fff}.s6,.lb6{--d:#09518d;--df:#09518d;--od:#fff}.lb6{left:17.30%;top:52.60%}
.ww[data-on="6"] .wp{--d:#09518d;--df:#09518d;--od:#fff}.s7,.lb7{--d:#7539ab;--df:#7539ab;--od:#fff}.lb7{left:26.88%;top:29.48%}
.ww[data-on="7"] .wp{--d:#7539ab;--df:#7539ab;--od:#fff}
.ww[data-on="0"] .s0 .bd,.ww[data-on="1"] .s1 .bd,.ww[data-on="2"] .s2 .bd,.ww[data-on="3"] .s3 .bd,.ww[data-on="4"] .s4 .bd,.ww[data-on="5"] .s5 .bd,.ww[data-on="6"] .s6 .bd,.ww[data-on="7"] .s7 .bd{fill:var(--df)}
.ww[data-on="0"] .s0 .sh,.ww[data-on="1"] .s1 .sh,.ww[data-on="2"] .s2 .sh,.ww[data-on="3"] .s3 .sh,.ww[data-on="4"] .s4 .sh,.ww[data-on="5"] .s5 .sh,.ww[data-on="6"] .s6 .sh,.ww[data-on="7"] .s7 .sh{transform:scale(1.04)}
.ww[data-on="0"] .s0 .ic,.ww[data-on="1"] .s1 .ic,.ww[data-on="2"] .s2 .ic,.ww[data-on="3"] .s3 .ic,.ww[data-on="4"] .s4 .ic,.ww[data-on="5"] .s5 .ic,.ww[data-on="6"] .s6 .ic,.ww[data-on="7"] .s7 .ic{stroke:var(--od)}
.ww[data-on="0"] .lb0,.ww[data-on="1"] .lb1,.ww[data-on="2"] .lb2,.ww[data-on="3"] .lb3,.ww[data-on="4"] .lb4,.ww[data-on="5"] .lb5,.ww[data-on="6"] .lb6,.ww[data-on="7"] .lb7{color:var(--od)}
.ww[data-on="0"] .p0,.ww[data-on="1"] .p1,.ww[data-on="2"] .p2,.ww[data-on="3"] .p3,.ww[data-on="4"] .p4,.ww[data-on="5"] .p5,.ww[data-on="6"] .p6,.ww[data-on="7"] .p7{visibility:visible}
